from pathlib import Path
import json, hashlib, re, subprocess, sys
root = Path('/Users/linus/Documents/code/qinglong/ql/data/scripts/bdc')
target = sys.argv[1]
source = sys.argv[2]
assert re.fullmatch(r'[0-9a-f]{40}', target)
assert re.fullmatch(r'[0-9a-f]{40}', source)
def run(arguments):
    result = subprocess.run(arguments, cwd=root, capture_output=True, text=True, timeout=90)
    if result.returncode: raise RuntimeError(result.stdout + result.stderr)
    return result.stdout.strip()
assert not run(['git', 'status', '--porcelain'])
assert run(['git', 'branch', '--show-current']) == 'master'
assert run(['git', 'rev-parse', 'HEAD']) == source
run(['git', 'fetch', 'origin', 'master'])
assert run(['git', 'rev-parse', 'FETCH_HEAD']) == target
run(['git', 'merge-base', '--is-ancestor', source, target])
changed = run(['git', 'diff', '--name-only', source, target]).splitlines()
assert changed and all(name.startswith('docs/') for name in changed), changed
run(['git', 'merge', '--ff-only', '--quiet', target])
assert run(['git', 'rev-parse', 'HEAD']) == target
for name, sha in EXPECTED['files'].items():
    assert hashlib.sha256((root / name).read_bytes()).hexdigest() == sha, name
assert hashlib.sha256((root / 'ai-config.js').read_bytes()).hexdigest() == EXPECTED['privateConfigSha256']
state = json.loads(run(['/usr/local/bin/docker', 'inspect', 'bdc']))[0]['State']
assert state['Running'] and state['Health']['Status'] == 'healthy'
assert not run(['git', 'status', '--porcelain'])
print(json.dumps({'head': target, 'sourceCommit': source, 'release': EXPECTED['release'], 'docsOnly': True, 'runtimeSourceFilesVerified': len(EXPECTED['files']), 'containerHealth': state['Health']['Status'], 'privateConfigPreserved': True, 'worktreeClean': True, 'containerStartedAt': state['StartedAt']}, ensure_ascii=False))
